insert into public.posts
  (author_name, org, category, title, content, visibility, source, source_url, created_at)
select '도쿄대학 한국인학생회', 'YB', e->>2, e->>0,
       (e->>1) || chr(10) || chr(10) ||
       '도쿄대학 한국인학생회 페이스북에서 옮겨온 글입니다.' || chr(10) ||
       '원문 보기 : ' || (e->>4),
       e->>3, 'facebook', e->>4, (e->>5)::timestamptz
  from src
 where not exists (select 1 from public.posts p
                    where p.org = 'YB' and p.source_url = e->>4);
